@dataclass
class EvalResult:
    """
    Container for evaluation results for a single trace.

    This dataclass provides structured access to trace evaluation data,
    replacing dict-based access for better type safety.
    """

    trace_id: str
    """The trace ID"""

    assessments: list[Assessment]
    """List of Assessment objects for this trace"""


@dataclass
class TableOutput:
    """Container for formatted table data."""

    headers: list[str]
    rows: list[list[Cell]]


def _format_assessment_cell(assessment: Assessment | None) -> Cell:
    """
    Format a single assessment cell for table display.

    Args:
        assessment: Assessment object with result, rationale, and error fields

    Returns:
        Cell object with formatted value and assessment metadata
    """
    if not assessment:
        return Cell(value=NA_VALUE)

    if assessment.error:
        display_value = f"error: {assessment.error}"
    elif assessment.result is not None and assessment.rationale:
        display_value = f"value: {assessment.result}, rationale: {assessment.rationale}"
    elif assessment.result is not None:
        display_value = f"value: {assessment.result}"
    elif assessment.rationale:
        display_value = f"rationale: {assessment.rationale}"
    else:
        display_value = NA_VALUE

    return Cell(value=display_value, assessment=assessment)


def extract_assessments_from_results(
    results_df: pd.DataFrame, evaluation_run_id: str
) -> list[EvalResult]:
    """Extract assessments created by an evaluation run from its results table."""
    output_data = []

    for _, row in results_df.iterrows():
        assessments = []
        for assessment_data in row.get("assessments", []):
            source_run_id = assessment_data.get("metadata", {}).get(
                AssessmentMetadataKey.SOURCE_RUN_ID
            )
            if source_run_id != evaluation_run_id:
                continue

            feedback = assessment_data.get("feedback")
            result = feedback.get("value") if isinstance(feedback, dict) else None
            error = assessment_data.get("error")
            assessments.append(
                Assessment(
                    name=assessment_data.get("assessment_name"),
                    result=result,
                    rationale=assessment_data.get("rationale"),
                    error=str(error) if error else None,
                )
            )

        if not assessments:
            assessments.append(
                Assessment(name=NA_VALUE, error="No assessments found on trace")
            )

        output_data.append(
            EvalResult(trace_id=row.get("trace_id", "unknown"), assessments=assessments)
        )

    return output_data


def format_table_output(output_data: list[EvalResult]) -> TableOutput:
    """Format evaluation results as trace rows and assessment columns."""
    assessment_names = sorted(
        {
            assessment.name
            for result in output_data
            for assessment in result.assessments
            if assessment.name not in (None, NA_VALUE)
        }
    )
    headers = ["trace_id", *assessment_names]
    rows = []

    for result in output_data:
        assessments_by_name = {
            assessment.name: assessment for assessment in result.assessments
        }
        rows.append(
            [Cell(value=result.trace_id)]
            + [
                _format_assessment_cell(assessments_by_name.get(name))
                for name in assessment_names
            ]
        )

    return TableOutput(headers=headers, rows=rows)


def resolve_scorers(scorer_names: list[str], experiment_id: str) -> list[Scorer]:
    """Resolve built-in scorer class/snake-case names and registered scorers."""
    built_in_scorers = get_all_scorers()
    built_in_by_name = {
        name: scorer
        for scorer in built_in_scorers
        for name in (scorer.__class__.__name__, scorer.name)
    }

    resolved_scorers = []
    for scorer_name in scorer_names:
        if scorer := built_in_by_name.get(scorer_name):
            resolved_scorers.append(scorer)
            continue

        try:
            resolved_scorers.append(
                get_scorer(name=scorer_name, experiment_id=experiment_id)
            )
        except MlflowException as e:
            available_scorers = ", ".join(sorted(built_in_by_name))
            raise click.UsageError(
                f"Scorer '{scorer_name}' not found. Available built-in scorers: "
                f"{available_scorers}. Error: {e}"
            ) from e

    if not resolved_scorers:
        raise click.UsageError("No valid scorers specified")

    return resolved_scorers























